import random

class Resp:
    def __init__(self, status_code, headers=None):
        self.status_code, self.headers = status_code, headers or {}

def scripted(*outcomes):
    queue = list(outcomes)
    def call():
        item = queue.pop(0)
        if item == "timeout":
            raise TimeoutError()
        return item
    return call

RETRY = {429, 500, 502, 503, 504}

def retry(call, sleep, rng, max_attempts=4):
    waits = []
    for attempt in range(1, max_attempts + 1):
        try:
            response = call()
        except TimeoutError:
            response = None
        if response is not None and response.status_code not in RETRY:
            return response.status_code, waits
        if attempt == max_attempts:
            raise RuntimeError(f"gave up after {attempt} attempts")
        header = response.headers.get("Retry-After", "") if response is not None else ""
        wait = float(header) if header.isdigit() else rng.uniform(0, min(8.0, 0.5 * 2 ** attempt))
        waits.append(round(wait, 2))
        sleep(wait)

slept = []
rng = random.Random(7)
print(retry(scripted("timeout", Resp(503), Resp(200)), slept.append, rng))
print(retry(scripted(Resp(404)), slept.append, rng))
print(retry(scripted(Resp(429, {"Retry-After": "3"}), Resp(200)), slept.append, rng))
try:
    retry(scripted(*[Resp(500)] * 4), slept.append, rng)
except RuntimeError as err:
    print(err)

