class RateLimitedAPI:
    def __init__(self, every=3):
        self.calls, self.every = 0, every

    def get_page(self, page):
        self.calls += 1
        if self.calls % self.every == 0:
            return 429, {"Retry-After": "2"}, None
        return 200, {}, list(range((page - 1) * 20 + 1, page * 20 + 1))

def read_all(api, waits):
    ids = []
    for page in (1, 2, 3):
        while True:
            status, headers, data = api.get_page(page)
            if status != 429:
                break
            waits.append(int(headers["Retry-After"]))
        ids += data
    return ids

api, waits = RateLimitedAPI(), []
ids = read_all(api, waits)
print(len(ids), api.calls, waits)
